CREATE VIEW belk.blk_missing_an_store_master (`department` Nullable(String), `class` Nullable(String), `subclass` Nullable(String), `insert_statement` Nullable(String)) AS SELECT DISTINCT department, class, subclass, concat('insert into blk_an_store_master_tbl select selling_channel,channel,s5_cluster,location,\'', department, '\' as x_department,\'', class, '\' as x_class,\'', subclass, '\' as x_subclass,time,year,str_grade,aps_index,bi,str_segmentation,str_sub_segmentation,str_aa_ind,str_state,str_climate,indx,eventdate from blk_an_store_master_tbl where department = \'DP-265\' AND class = \'CL-2630\' and subclass = \'SL-2630\';') AS insert_statement FROM belk.blk_stylecolor_hier_attr_tbl WHERE (department, class, subclass) NOT IN (SELECT DISTINCT department, class, subclass FROM belk.blk_an_store_master_tbl)
CREATE VIEW belk.blk_missing_an_time_class_sales_rank (`department` Nullable(String), `subclass` Nullable(String), `class` Nullable(String), `insert_statement` Nullable(String)) AS SELECT DISTINCT department, subclass, class, concat('insert into blk_an_time_class_sales_rank_tbl select location,s5_cluster,s5_channel,\'', department, '\' as x_department, \'', subclass, '\' as x_subclass, \'', class, '\' as x_class, 1 as slsrnk,1 as class_avg,1 as rank_mult,1 as elas_factor,dbt_wk,eventdate,sell_thru,hist_sell_thru from blk_an_time_class_sales_rank_tbl where department = \'DP-265\' AND class = \'CL-2630\' and subclass = \'SL-2630\';') AS insert_statement FROM belk.blk_stylecolor_hier_attr_tbl WHERE (department, class, subclass) NOT IN (SELECT DISTINCT department, class, subclass FROM belk.blk_an_time_class_sales_rank_tbl)
