CREATE VIEW belk.blk_p_mfp_dept_month_view_hier (`product` String, `supplier_site_id` Nullable(String), `time` String, `plan_type` Nullable(String), `eop_tot_rtl` Nullable(Float32), `gm_tot_rtl` Nullable(Float32), `rcpts_grs_rtl` Nullable(Float32), `sls_tot_rtl` Nullable(Float32), `eventdate` Date, `department` Nullable(String), `group_id` Nullable(String), `division` Nullable(String), `total_brand` Nullable(String), `month` Nullable(String), `quarter` Nullable(String), `season` Nullable(String), `year` Nullable(String)) AS SELECT product, supplier_site_id, time, plan_type, eop_tot_rtl, gm_tot_rtl, rcpts_grs_rtl, sls_tot_rtl, eventdate, department, group_id, division, total_brand, id AS month, ancestor0 AS quarter, ancestor1 AS season, ancestor2 AS year FROM (SELECT product, supplier_site_id, time, plan_type, eop_tot_rtl, gm_tot_rtl, rcpts_grs_rtl, sls_tot_rtl, eventdate, department, group_id, division, total_brand, time AS id FROM belk.blk_p_mfp_tbl ANY LEFT JOIN (SELECT department, department AS product, group_id, division, total_brand, count(*) AS cnt FROM belk.blk_stylecolor_hier_attr WHERE (department IN (SELECT DISTINCT product FROM belk.blk_p_mfp_tbl)) AND ((stylecolor, updated_at) IN (SELECT product, max(updated_at) FROM belk.blk_stylecolor_hier_attr GROUP BY product)) GROUP BY department, group_id, division, total_brand ORDER BY count(*) DESC LIMIT 1 BY department) USING (product)) AS x ANY LEFT JOIN belk.blk_h_timestd_tbl USING (id)
